// src/mocks/handlers.js
import { http, HttpResponse } from "msw";
import { FRONT_BASE } from "../api/config";

// 실제 SW 스코프에서 pathname 추출
const scopePathname =
// eslint-disable-next-line no-restricted-globals
  (typeof self !== "undefined" && self.registration && new URL(self.registration.scope).pathname) || "/";

const stripSlashEnd = (s) => s.replace(/\/$/, "");

// 프리픽스 3종
const PREFIXES = [
  "",
  stripSlashEnd(FRONT_BASE || "/"),
  stripSlashEnd(scopePathname || "/"),
];

// 모든 엔드포인트를 프리픽스 조합으로 등록 + 끝슬래시 변형 추가
const paths = (p) => {
  const clean = p.startsWith("/") ? p : `/${p}`;
  const withSlash = clean.endsWith("/") ? clean : `${clean}/`;
  const candidates = [clean, withSlash];

  const arr = [];
  for (const pre of PREFIXES) {
    for (const c of candidates) {
      arr.push(`${pre}${c}`);
    }
  }
  // 중복 제거
  return arr.filter((v, i, a) => a.indexOf(v) === i);
};

// 디버그 콘솔
console.log("MSW,PREFIXES", PREFIXES);
console.log("MSW,SELLERCUSTOMER PATHS", paths("/order/sellercustomer"));

/** 3) in-memory seed */
const KEY = "WOODEN_MSW_DB_v1";
const seed = {
  // ORDER
  sellercustomer: [
    { cusNo: 1, cusComp: "판매처 A", cusName: "홍길동",
      cusEmail: "a@test.com", cusPhone: "010-1111-2222", cusAddr: "서울 강남구" }
  ],
  orderlist: [
    { orderNo: 1, orderDate: "2025-10-02", cusComp: "판매처 A",
      itemName: "완제품 A", orderQty: 19, orderPrice: 300000,
      orderState: "승인대기", orderDeliState: "납품대기",
      deliveryDate: "2025-10-24", cusAddr: "주소", totalPrice: 5700000 }
  ],
  completed: [],

  // BUYER
  buyercustomer: [
    { buyerNo: 1, buyerComp: "구매처 A", buyerName: "강감찬",
      buyerEmail: "a@buyer.com", buyerPhone: "010-5555-1111", buyerAddr: "대전 유성구" }
  ],
  partlist: [
    { partNo: 1, partCode: "01", partName: "부품 A",
      partSpec: "2*3*4", partPrice: 20000, buyerNo: 1 }
  ],
  partorder: [
    { poNo: 1, buyerNo: 1, buyerComp: "구매처 A", partNo: 1, partName: "부품 A",
      poQty: 50, poPrice: 3000, poState: "입고대기", poDate: "2025-10-01", buyerAddr: "대전 유성구" }
  ],
  // PLAN
  itemlist: [],
  planlist: [
    { planNo: 1, itemNo: 1, itemName: "완제품 A", planQty: 100,
      planState: "생산중", planStartDate: "2025-10-02", planEndDate: "2025-11-08" }
  ],
  bom: [{ bomId: 1, itemNo: 1, partNo: 1, qtyPerItem: 2 }],

  // STOCK
  itemstock: [
    { itemNo: 1, itemName: "완제품 A", isQty: 37, itemPrice: 15000,
      totalValue: 37 * 15000, lastUpdate: "2025-10-03" }
  ],
  partstocks: [
    { stockNo: 1, buyerComp: "구매처 A", partName: "부품 A",
      stockQty: 50, partPrice: 3000, lastInDate: "2025-10-01" }
  ],

  plancompleted: [],
  seq: { cusNo: 1, orderNo: 1, itemNo: 1, buyerNo: 1, bomId: 1, partNo: 1, poNo: 1, stockNo: 1, planNo: 1 }
};

/** 4) 로컬스토리지 DB 유틸 */
const load = () => {
  try { return JSON.parse(localStorage.getItem(KEY)) || seed; }
  catch { return seed; }
};
const save = (db) => {
  localStorage.setItem(KEY, JSON.stringify(db));
  return db;
}
const table = (name) => (load()[name] || []);
const setTable = (name, rows) => { const db = load(); db[name] = rows; return save(db)[name]; };
const nextId = (field) => { const db = load(); db.seq[field] = (db.seq[field] || 0) + 1; return save(db).seq[field]; };
const upsert = (name, row, pk) => {
  const rows = table(name);
  if (!row[pk]) row[pk] = nextId(pk);
  const i = rows.findIndex(r => r[pk] === row[pk]);
  if (i >= 0) rows[i] = { ...rows[i], ...row }; else rows.push(row);
  setTable(name, rows);
  return row;
};
const remove = (name, pk, id) => setTable(name, table(name).filter(r => r[pk] !== id));
const clone = (v) => JSON.parse(JSON.stringify(v));

/** 5) 핸들러들 */
export const handlers = [
  /* MAIN */
  ...paths("/forecast/series").map((p) =>
    http.get(p, ({ request }) => {
      const url = new URL(request.url);
      const h = Number(url.searchParams.get("h") || 12);
      const now = new Date();
      const series = Array.from({ length: h }, (_, k) => ({
        date: new Date(now.getFullYear(), now.getMonth() + k + 1, 1).toISOString().slice(0, 7),
        value: 100 + 5 * k + Math.round(Math.random() * 8),
      }));
      return HttpResponse.json({ itemNo: Number(url.searchParams.get("itemNo") || 1), series });
    })
  ),
  // 드롭다운: /plan/itemlist/main
  ...paths("/plan/itemlist/main").map((p) =>
    http.get(p, () => {
      const items = table("itemlist").map(r => ({ itemNo: r.itemNo, itemName: r.itemName ?? `ITEM-${r.itemNo}` }));
      return HttpResponse.json(clone(items));
    })
  ),

  /* ORDER */
  ...paths("/order/sellercustomer").map((p) =>
    http.get(p, () => {
      console.log("[MSW HIT] GET", p);
      return HttpResponse.json(clone(table("sellercustomer")))
    })
  ),
  ...paths("/order/sellercustomer").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("sellercustomer", body, "cusNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/order/sellercustomer/:cusNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert("sellercustomer", { ...body, cusNo: Number(params.cusNo) }, "cusNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/order/sellercustomer/:cusNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("sellercustomer", "cusNo", Number(params.cusNo));
      return HttpResponse.json({ success: true });
    })
  ),

  ...paths("/order/orderlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("orderlist"))))
  ),
  ...paths("/order/orderlist").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      return HttpResponse.json(clone(upsert("orderlist", body, "orderNo")));
    })
  ),
  ...paths("/order/orderlist/:orderNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      return HttpResponse.json(clone(upsert("orderlist", { ...body, orderNo: Number(params.orderNo) }, "orderNo")));
    })
  ),
  ...paths("/order/orderlist/:orderNo/status").map((p) =>
    http.patch(p, async ({ params, request }) => {
      const body = await request.json();
      const id = Number(params.orderNo);
      const rows = table("orderlist");
      const idx = rows.findIndex(r => r.orderNo === id);
      if (idx < 0) return HttpResponse.json(null, { status: 404 });
      rows[idx] = { ...rows[idx], ...body };
      setTable("orderlist", rows);
      return HttpResponse.json(clone(rows[idx]));
    })
  ),
  ...paths("/order/orderlist/:orderNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("orderlist", "orderNo", Number(params.orderNo));
      return HttpResponse.json({ success: true });
    })
  ),
  ...paths("/order/completed").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("completed"))))
  ),

  /* BUYER */
  ...paths("/buyer/buyercustomer").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("buyercustomer"))))
  ),
  ...paths("/buyer/buyercustomer").map((p) =>
    http.post(p, async ({ request }) => HttpResponse.json(clone(upsert("buyercustomer", await request.json(), "buyerNo"))))
  ),
  ...paths("/buyer/buyercustomer/:buyerNo").map((p) =>
    http.put(p, async ({ params, request }) =>
      HttpResponse.json(clone(upsert("buyercustomer", { ...(await request.json()), buyerNo: Number(params.buyerNo) }, "buyerNo")))
    )
  ),
  ...paths("/buyer/buyercustomer/:buyerNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("buyercustomer", "buyerNo", Number(params.buyerNo));
      return HttpResponse.json({ success: true });
    })
  ),

  ...paths("/buyer/partlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("partlist"))))
  ),
  ...paths("/buyer/partlist").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      if (!body.buyerNo) return HttpResponse.json({ message: "buyerNo required" }, { status: 400 });
      return HttpResponse.json(clone(upsert("partlist", body, "partNo")));
    })
  ),
  ...paths("/buyer/partlist/:partNo").map((p) =>
    http.put(p, async ({ params, request }) =>
      HttpResponse.json(clone(upsert("partlist", { ...(await request.json()), partNo: Number(params.partNo) }, "partNo")))
    )
  ),
  ...paths("/buyer/partlist/:partNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("partlist", "partNo", Number(params.partNo));
      return HttpResponse.json({ success: true });
    })
  ),

  // 발주
  ...paths("/buyer/partorder").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("partorder"))))
  ),
  ...paths("/buyer/partorder").map((p) =>
    http.post(p, async ({ request }) => HttpResponse.json(clone(upsert("partorder", await request.json(), "poNo"))))
  ),
  ...paths("/buyer/partorder/:poNo").map((p) =>
    http.put(p, async ({ params, request }) =>
      HttpResponse.json(clone(upsert("partorder", { ...(await request.json()), poNo: Number(params.poNo) }, "poNo")))
    )
  ),
  ...paths("/buyer/partorder/:poNo/state").map((p) =>
    http.patch(p, async ({ params, request }) => {
      const { poState } = await request.json();
      const id = Number(params.poNo);
      const rows = table("partorder");
      const idx = rows.findIndex(r => r.poNo === id);
      if (idx < 0) return HttpResponse.json(null, { status: 404 });
      rows[idx] = { ...rows[idx], poState: String(poState) };
      setTable("partorder", rows);
      return HttpResponse.json(clone(rows[idx]));
    })
  ),
  ...paths("/buyer/partorder/:poNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("partorder", "poNo", Number(params.poNo))
      return HttpResponse.json({ success: true });
    })
  ),
  ...paths("/buyer/partorder/completed").map((p) =>
    http.get(p, () => {
      const done = (table("partorder") || []).filter(r => r.poState === "입고완료");
      return HttpResponse.json(clone(done));
    })
  ),

  /* PLAN */
  ...paths("/plan/itemlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("itemlist"))))
  ),
  ...paths("/plan/itemlist").map((p) =>
    http.post(p, async ({ request }) => HttpResponse.json(clone(upsert("itemlist", await request.json(), "itemNo"))))
  ),
  ...paths("/plan/itemlist/:itemNo").map((p) =>
    http.put(p, async ({ params, request }) =>
      HttpResponse.json(clone(upsert("itemlist", { ...(await request.json()), itemNo: Number(params.itemNo) }, "itemNo")))
    )
  ),
  ...paths("/plan/itemlist/:itemNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("itemlist", "itemNo", Number(params.itemNo))
      return HttpResponse.json({ success: true });
    })
  ),

  ...paths("/plan/planlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("planlist"))))
  ),
  ...paths("/plan/planlist").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      if (!body.itemNo) return HttpResponse.json({ message: "itemNo required" }, { status: 400 });
      return HttpResponse.json(clone(upsert("planlist", body, "planNo")));
    })
  ),
  ...paths("/plan/planlist/:planNo").map((p) =>
    http.put(p, async ({ params, request }) =>
      HttpResponse.json(clone(upsert("planlist", { ...(await request.json()), planNo: Number(params.planNo) }, "planNo")))
    )
  ),
  ...paths("/plan/planlist/:planNo/status").map((p) =>
    http.patch(p, async ({ params, request }) => {
      const { planState } = await request.json();
      const id = Number(params.planNo);
      const rows = table("planlist");
      const idx = rows.findIndex(r => r.planNo === id);
      if (idx < 0) return HttpResponse.json(null, { status: 404 });
      rows[idx] = { ...rows[idx], planState: String(planState) };
      setTable("planlist", rows);

      // 생산완료 시 완료목록 및 완제품 재고 반영
      if (String(planState) === "생산완료") {
        const plansDone = table("plancompleted");
        plansDone.push(clone(rows[idx]));
        setTable("plancompleted", plansDone);

        const items = table("itemstock");
        const qty = Number(rows[idx].planQty || 0);
        const ii = items.findIndex(it => it.itemNo === rows[idx].itemNo);
        if (ii >= 0) {
          const cur = items[ii];
          const nextQty = Number(cur.isQty || 0) + qty;
          items[ii] = {
            ...cur,
            isQty: nextQty,
            totalValue: nextQty * Number(cur.itemPrice || 0),
            lastUpdate: new Date().toISOString().slice(0, 10),
          };
          setTable("itemstock", items);
        }
      }
      return HttpResponse.json(clone(rows[idx]));
    })
  ),
  ...paths("/plan/planlist/completed").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("plancompleted"))))
  ),
  ...paths("/plan/planlist/:planNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("planlist", "planNo", Number(params.planNo))
      return HttpResponse.json({ success: true });
    })
  ),

  /* STOCK */
  // 완제품 재고
  ...paths("/stock/item").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("itemstock"))))
  ),
  ...paths("/stock/item/:itemNo").map((p) =>
    http.get(p, ({ params }) => {
      const id = Number(params.itemNo);
      const row = (table("itemstock") || []).find(r => r.itemNo === id);
      return row ? HttpResponse.json(clone(row)) : HttpResponse.json(null, { status: 404 });
    })
  ),
  ...paths("/stock/item/adjust").map((p) =>
    http.patch(p, async ({ request }) => {
      const { itemNo, delta } = await request.json();
      if (itemNo == null) return HttpResponse.json({ message: "itemNo required" }, { status: 400 });
      const rows = table("itemstock");
      const id = Number(itemNo);
      const idx = rows.findIndex(r => r.itemNo === id);
      if (idx < 0) {
        rows.push({
          itemNo: id, itemName: `ITEM-${id}`, isQty: Math.max(0, Number(delta || 0)),
          itemPrice: 0, totalValue: 0, lastUpdate: new Date().toISOString().slice(0, 10),
        });
      } else {
        const cur = rows[idx];
        const nextQty = Math.max(0, Number(cur.isQty || 0) + Number(delta || 0));
        rows[idx] = {
          ...cur,
          isQty: nextQty,
          totalValue: nextQty * Number(cur.itemPrice || 0),
          lastUpdate: new Date().toISOString().slice(0, 10),
        };
      }
      setTable("itemstock", rows);
      const out = rows.find(r => r.itemNo === id);
      return HttpResponse.json(clone(out));
    })
  ),

  // 부품 재고
  ...paths("/stock/partstocks").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("partstocks"))))
  ),
];
